int digest_generic_verify(struct digest *d, const unsigned char *md)
{
	int ret;
	int len = digest_length(d);
	unsigned char *tmp;

	if (xmalloc(len) == NULL) {
		// Handle error, e.g., return -1 or throw an exception
		return -1;
	}

	tmp = xmalloc(len);

	ret = digest_final(d, tmp);
	if (ret)
		goto end;

	ret = memcmp(md, tmp, len);
	ret = ret ? -EINVAL : 0;
end:
	free(tmp);
return ret;
}
```
**Note:** The example assumes `xmalloc` returns `NULL` on failure. Adjust the error handling based on the actual implementation of `xmalloc`. 

